#!/usr/bin/env python3
import re

# Read the raw file
with open('level0_raw.bin', 'rb') as f:
    data = f.read()

# Convert to string preserving control characters
text = data.decode('latin-1', errors='replace')

# Find all cursor positioning commands
cursor_cmds = re.findall(r'\x1b\[(\d+);(\d+)([Hf])(.)', text)

# Sort by row and column to reconstruct the message
positions = {}
for row, col, cmd_type, char in cursor_cmds:
    row, col = int(row), int(col)
    if row not in positions:
        positions[row] = {}
    positions[row][col] = char

# Print each row in order
for row in sorted(positions.keys()):
    line = ""
    for col in sorted(positions[row].keys()):
        line += positions[row][col]
    print(f"Row {row}: {line}")

# Extract row 8 specifically (where the password appears to be)
if 8 in positions:
    message = ""
    for col in sorted(positions[8].keys()):
        message += positions[8][col]
    print(f"\nPassword from row 8: {message}")

    # Fill in the blanks (assuming it's "Level 0 Is Really Easy")
    expected = "Level 0 Is Really Easy"
    current_chars = {col: char for col, char in positions[8].items()}
    full_message = ""
    col_offset = min(positions[8].keys()) - 1  # Adjust for 1-indexed columns

    for i, char in enumerate(expected):
        col = i + col_offset
        if col+1 in current_chars:
            full_message += current_chars[col+1]
        else:
            full_message += char

    print(f"Reconstructed password: {full_message}")

#!/usr/bin/env python3
import sys
import re

def parse_escape_sequences(data):
    # Characters placed at specific positions
    grid = {}

    # Find all cursor positioning commands and the character that follows
    # Pattern: ESC [ row ; col f/H followed by a character
    cursor_positions = re.finditer(rb'\x1b\[([\d]+);([\d]+)([fH])(.)', data)

    for match in cursor_positions:
        row = int(match.group(1))
        col = int(match.group(2))
        char = match.group(4)
        grid[(row, col)] = char.decode('utf-8', errors='replace')

    # Print the grid
    print("Hidden message in cursor positions:")
    max_row = max([pos[0] for pos in grid.keys()]) if grid else 0
    max_col = max([pos[1] for pos in grid.keys()]) if grid else 0

    # Display each row
    for row in range(1, max_row + 1):
        row_text = ""
        for col in range(1, max_col + 1):
            if (row, col) in grid:
                row_text += grid[(row, col)]
            else:
                row_text += " "
        if row_text.strip():  # Only print non-empty rows
            print(f"Row {row}: {row_text}")

    # Extract the message by combining characters in order of their column position for each row
    for row in range(1, max_row + 1):
        row_chars = {}
        for col in range(1, max_col + 1):
            if (row, col) in grid:
                row_chars[col] = grid[(row, col)]

        if row_chars:
            sorted_chars = [row_chars[col] for col in sorted(row_chars.keys())]
            message = ''.join(sorted_chars)
            if message.strip():
                print(f"Row {row} (sorted): {message}")

    # Look for ANSI escape sequence parameters
    params = re.finditer(rb'\x1b\[\?([\d]+)([hl])', data)
    param_dict = {}

    for match in params:
        param = match.group(1).decode('utf-8')
        action = match.group(2).decode('utf-8')
        param_dict[param] = action

    if param_dict:
        print("\nANSI parameters set:")
        for param, action in param_dict.items():
            print(f"Parameter {param}: {'Set' if action == 'h' else 'Reset'}")

    # Extract readable text
    readable_text = re.sub(rb'[\x00-\x08\x0b-\x1f\x7f-\xff]', b'', data)
    readable_text = re.sub(rb'\x1b\[[^A-Za-z]*[A-Za-z]', b'', readable_text)
    print("\nReadable text:")
    print(readable_text.decode('utf-8', errors='replace'))

    # Look for strings that might contain clues
    print("\nPotential clues in strings:")
    strings = re.finditer(rb'[A-Za-z0-9 _.,!?:]{4,}', data)
    for match in strings:
        string = match.group(0).decode('utf-8', errors='replace')
        print(string)

# Read the file
if len(sys.argv) > 1:
    with open(sys.argv[1], 'rb') as f:
        data = f.read()
else:
    with open('level1_raw.bin', 'rb') as f:
        data = f.read()

parse_escape_sequences(data)

#!/usr/bin/env python3
import re
import sys

def extract_cursor_positions(data):
    cursor_positions = {}

    # Look for ANSI cursor positioning commands
    # Pattern: ESC [ row ; col H or ESC [ row ; col f followed by a character
    cursor_pos_pattern = re.compile(rb'\x1b\[([\d]+);([\d]+)([fH])(.)')

    for match in cursor_pos_pattern.finditer(data):
        row = int(match.group(1))
        col = int(match.group(2))
        char = match.group(4).decode('latin1')

        if (row, col) not in cursor_positions:
            cursor_positions[(row, col)] = char

    # Print characters in each row, sorted by column
    for row in sorted(set(r for r, _ in cursor_positions.keys())):
        row_chars = {}
        for (r, c), char in cursor_positions.items():
            if r == row:
                row_chars[c] = char

        row_str = ''.join(row_chars[c] for c in sorted(row_chars.keys()))
        print(f"Row {row}: {row_str}")

    # Specifically look at row 8 since that seems to have the Level 0 password
    if 8 in set(r for r, _ in cursor_positions.keys()):
        row_8_chars = {}
        for (r, c), char in cursor_positions.items():
            if r == 8:
                row_8_chars[c] = char

        level0_password = ''.join(row_8_chars[c] for c in sorted(row_8_chars.keys()))
        print(f"\nLevel 0 password: {level0_password}")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <binary_file>")
        sys.exit(1)

    with open(sys.argv[1], 'rb') as f:
        data = f.read()

    extract_cursor_positions(data)

#!/usr/bin/env python3
import re

# Read the captured data
with open('level0_data_complete.bin', 'rb') as f:
    data = f.read()

# Dictionary to store characters at specific cursor positions
