# Pattern for both formats: \e[row;colH and \e[row;colf
cursor_pattern = re.compile(rb'\x1b\[(\d+);(\d+)([Hf])(.)')

for match in cursor_pattern.finditer(data):
    row = int(match.group(1))
    col = int(match.group(2))
    char = match.group(4).decode('latin1')

    # Store the character at this position
    cursor_positions[(row, col)] = char

# Count occurrences of each row to see where the message might be
row_counts = {}
for (row, _) in cursor_positions.keys():
    row_counts[row] = row_counts.get(row, 0) + 1

print("Row counts:")
for row, count in sorted(row_counts.items()):
    print(f"Row {row}: {count} characters")

# Extract messages for rows with significant character counts
for row in sorted(row_counts.keys()):
    if row_counts[row] > 5:  # Only rows with several characters
        positions = {}
        for (r, c), char in cursor_positions.items():
            if r == row:
                positions[c] = char

        # Sort by column to get the correct order
        message = ''.join(positions[col] for col in sorted(positions.keys()))
        print(f"Row {row} message: {message}")
